#!/usr/bin/env node
// make-embed-bundle — emit the ONE embeddable stylesheet.
//
// The "load BOTH" contract (src/lib/web-styles.mjs) says an embedder needs
// base.css + the brand vars + a resolvable Inter TOGETHER. previewStyles()
// shares the assembly, but every embedder still supplies baseCss/fontUrl its
// own way. This emits the whole contract as one artifact instead:
//
//   public/embed/bundle.css  =  brand vars + base.css + @font-face (base64 Inter)
//
// Deployed, that's https://jseverino.com/embed/bundle.css — the vault theme,
// the Obsidian cockpit, or any future panel consumes one URL (or this one
// file), and cannot forget the brand vars. Emit once, embed everywhere.
//
//   node bin/make-embed-bundle.mjs           # (re)write public/embed/bundle.css
//   node bin/make-embed-bundle.mjs --check   # fail if the committed copy is stale
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { brandVarsCss } from '../src/lib/brand.mjs';
import { readCssEntry } from './lib/css-entry.mjs';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const outPath = path.join(root, 'public', 'embed', 'bundle.css');

const baseCss = readCssEntry(path.join(root, 'src', 'styles', 'base.css'));
const font = fs.readFileSync(
  path.join(root, 'public', 'assets', 'fonts', 'inter', 'inter-variable-latin.woff2'),
);

const bundle = [
  '/* GENERATED by bin/make-embed-bundle.mjs — do not edit.',
  ' * The one embeddable stylesheet: brand vars + base.css + inlined Inter.',
  ' * Regenerate: npm run -s make:embed · drift-gated by check:embed. */',
  brandVarsCss(),
  baseCss,
  `@font-face{font-family:Inter;font-weight:100 900;font-style:normal;font-display:swap;src:url(data:font/woff2;base64,${font.toString('base64')}) format('woff2')}`,
  '',
].join('\n');

if (process.argv.includes('--check')) {
  const current = fs.existsSync(outPath) ? fs.readFileSync(outPath, 'utf8') : '';
  if (current !== bundle) {
    console.error('embed bundle is stale — run: npm run -s make:embed');
    process.exit(1);
  }
  console.log('embed bundle current (public/embed/bundle.css)');
  process.exit(0);
}

fs.mkdirSync(path.dirname(outPath), { recursive: true });
fs.writeFileSync(outPath, bundle);
console.log(`wrote ${path.relative(root, outPath)} (${(bundle.length / 1024).toFixed(0)} kB)`);
